var schema31 = { "$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://ethrfps.app/schemas/v1.0.0/opportunity.schema.json", "title": "RFP Hub Opportunity", "description": "RFP Hub Standard v1.0.0 \u2014 the normative definition of a funding opportunity in the Ethereum ecosystem. A document conforms to this version of the standard when it validates against this file. Covers six funding types: grant, hackathon, bounty, accelerator, vc_fund, rfp. Aligns conceptually with DAOIP-5 (Grants Metadata) and schema.org/Grant. Published under CC0 1.0 Universal. The field reference is FIELDS.md, the normative/informative split is NORMATIVE.md, and both ship alongside this file in the @the-rfp-hub/standard package and at https://github.com/The-RFP-Hub/the-rfp-hub.", "$comment": "AUTHORING NOTES (not for consumers). (1) `additionalProperties: false` at this level is safe alongside `allOf` only because no branch introduces an undeclared property name: each branch's `then` narrows `fundingDetails`, which is already declared in this object's `properties`, and every other name the branches mention is declared there too. That is the classic 2020-12 trap avoided by construction rather than by `unevaluatedProperties`, which is deliberately not used \u2014 it would relax this object from closed to 'closed after evaluation' for no gain. Any future branch that mentions a property name not declared here MUST be paired with a switch to `unevaluatedProperties: false`. The same reasoning applies inside $defs/deadline, whose `then` narrows `date`, a property already declared in its own `properties`. (2) Absence of `x-stability` means `stable`; only fields resting on narrow evidence are annotated `provisional`. (3) Property order is grouped identity \u2192 classification \u2192 organisations \u2192 provenance \u2192 content \u2192 money \u2192 time \u2192 fundingDetails, and `required` follows property order, so diffs stay reviewable.", "type": "object", "additionalProperties": false, "x-stability": "stable", "x-since": "1.0.0", "required": ["specVersion", "id", "fundingType", "title", "description", "status", "operatingOrganizations", "source", "fundingDetails"], "properties": { "$schema": { "type": "string", "format": "uri", "description": "Optional self-identification: the URL of the RFP Hub schema this document claims to conform to. Permitted so a generic validator can discover the contract from the instance alone. Ignored by validation \u2014 naming a different schema here does not change which schema the document is validated against.", "examples": ["https://ethrfps.app/schemas/v1.0.0/opportunity.schema.json"] }, "@context": { "anyOf": [{ "type": "string" }, { "type": "object" }, { "type": "array" }], "description": "Optional JSON-LD context: a URL, an inline context object, or an array of either. Permitted so an instance can be consumed as linked data. Ignored by validation \u2014 the standard makes no claim about its contents.", "examples": ["https://ethrfps.app/schemas/v1.0.0/context.jsonld"] }, "@type": { "anyOf": [{ "type": "string" }, { "type": "array" }], "description": "Optional JSON-LD type, or an array of types. Permitted so an instance can be consumed as linked data; ignored by validation.", "examples": ["schema:Grant"] }, "specVersion": { "type": "string", "const": "1.0.0", "description": "The RFP Hub Standard version this entry conforms to. Fixed at 1.0.0 for this schema. Consumers use it to select the correct validator.", "examples": ["1.0.0"] }, "id": { "type": "string", "minLength": 1, "maxLength": 128, "pattern": "^[A-Za-z0-9._:-]+$", "description": "Stable, unique identifier for the opportunity within the Hub. Immutable once assigned. A namespaced form is recommended but not required.", "examples": ["filecoin:propgf-batch-3", "fundingmap:1242"] }, "fundingType": { "type": "string", "enum": ["grant", "hackathon", "bounty", "accelerator", "vc_fund", "rfp"], "description": "The kind of funding opportunity, and the structural discriminator of the standard. Every entry carries its type-specific details in `fundingDetails`, whose own `fundingType` tag names that object's shape and always equals this field \u2014 the binding allOf below keeps the two in step \u2014 so consumers can dispatch on either tag. For grants the details may carry nothing beyond the tag.", "examples": ["grant", "rfp"] }, "title": { "type": "string", "minLength": 1, "maxLength": 300, "description": "Human-readable name of the opportunity." }, "description": { "type": "string", "minLength": 1, "description": "Full description of the opportunity. Markdown is permitted; consumers are advised to treat it as untrusted and sanitise before rendering." }, "summary": { "type": ["string", "null"], "maxLength": 500, "description": "Optional short teaser (roughly one or two sentences) for list and card views." }, "status": { "type": "string", "enum": ["upcoming", "open", "closed", "archived"], "description": "Lifecycle status of the opportunity. 'upcoming' = announced but not yet accepting applications, and also the value for a pre-open posting \u2014 there is no 'draft' status; 'open' = currently accepting; 'closed' = no longer accepting; 'archived' = withdrawn or retired. Editorial and review state (pending, rejected) is not represented here \u2014 it is server-side metadata.", "examples": ["open"] }, "sponsoringOrganizations": { "type": "array", "items": { "$ref": "#/$defs/organization" }, "description": "The organisations issuing or backing the opportunity \u2014 the issuer or backer, not necessarily the source of funds, because for donor-funded models the money's origin is deliberately not modelled. Optional, and may be absent or empty, when the operator is the only party to name or the backer is not published. The party running the process belongs in operatingOrganizations instead." }, "operatingOrganizations": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/organization" }, "description": "The organisations that actually run the opportunity \u2014 intake, process and the application funnel, whether on their own behalf or a sponsor's. Array order is semantic: entry 0 is the primary organisation and the one to display." }, "source": { "$ref": "#/$defs/provenance", "description": 'Provenance of this entry. Required as an object, but every field inside it is optional, so `"source": {}` validates. Provenance completeness is a data-quality and ingestion-policy concern rather than a schema constraint.' }, "ecosystems": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Ethereum-family ecosystems this opportunity targets. The RFP Hub is ETH-scoped, but this is an open, extensible list \u2014 not a closed enum, and deliberately not registry-governed either \u2014 so L2s and ETH-adjacent ecosystems are first-class and a newly launched one needs no process.", "examples": [["Optimism"], ["Ethereum", "Base"]] }, "categories": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Topical categories. Free text.", "examples": [["DeFi", "Public Goods"], ["Infrastructure", "Developer Tooling"]] }, "eligibility": { "type": ["string", "null"], "description": "Free text describing who may apply \u2014 stage, geography, jurisdiction, entity requirements, compliance constraints \u2014 in the publisher's own words. Deliberately unstructured: eligibility criteria vary too much across publishers to be comparable as data, so this field is for reading, not faceting.", "examples": ["Pre-seed to Series A teams. Global, excluding sanctioned jurisdictions. A registered legal entity is required before payout."] }, "prerequisites": { "type": ["string", "null"], "description": "Free text describing what a proposal must contain to be considered \u2014 track record, approach, milestone plan, disclosures. Distinct from rfp.requirements, which describes what the work must deliver.", "examples": ["A proposal must include prior track record, technical approach, a milestone plan with amounts, and disclosure of any conflicts."] }, "additionalReferences": { "type": ["string", "null"], "description": "A single free-form string of supporting links and references \u2014 guidelines, past rounds, forum threads, original postings. Deliberately one string rather than an array of URIs, because publishers paste what they have.", "examples": ["Original posting: https://forum.example.org/t/opsec-rfp/1 \xB7 Prior round retrospective: https://example.org/retro"] }, "serviceAgreement": { "type": ["string", "null"], "x-since": "1.0.0", "description": "Free text describing how a service-agreement arrangement works. Valid on any fundingType \u2014 an rfp or grant carrying it reads as a long-term service engagement. Presence of the field is the signal; duration and renewal live in the text if they matter. Not filterable or facetable, by design.", "examples": ["Runs as a rolling twelve-month engagement rather than a one-off deliverable; renewal is decided at the end of each term by the sponsoring foundation.", "Ongoing service-provider relationship, scoped annually, with a published scope-of-work and quarterly reporting."] }, "applicationUrl": { "type": ["string", "null"], "format": "uri", "description": "URL where applicants submit or apply \u2014 the only URL that points at the opportunity itself, and therefore the only link-back target. It may carry whatever the submission channel is, including a forum thread when no portal exists; the URL's kind is not typed. Clarifications go in description.", "examples": ["https://example.org/apply", "https://forum.example.org/t/rfp-thread/42"] }, "website": { "type": ["string", "null"], "format": "uri", "description": "Primary website for the opportunity or program." }, "logoUrl": { "type": ["string", "null"], "format": "uri", "description": "URL of the program or organisation logo image." }, "bannerUrl": { "type": ["string", "null"], "format": "uri", "description": "URL of a banner or hero image." }, "socialLinks": { "type": "array", "items": { "$ref": "#/$defs/socialLink" }, "uniqueItems": true, "description": "Social and community links for the opportunity or program, one entry per link. The same platform may appear in more than one entry when it has more than one URL; only whole-entry duplicates are rejected." }, "fundingInfo": { "$ref": "#/$defs/funding", "description": "Program-level funding envelope: single currency, total budget, amount committed to date, and the per-award range." }, "milestones": { "type": "array", "items": { "$ref": "#/$defs/milestone" }, "x-since": "1.0.0", "description": "Optional milestone sequence, valid on any fundingType. Array order is the milestone sequence \u2014 there is no order or index field. Milestone-based payment is expressed by this array together with grant.milestoneBased; there is no separate payment-schedule concept.", "$comment": "Deliberately not uniqueItems: every property of a milestone is optional, so two sparsely-populated entries can legitimately be byte-identical while denoting different milestones distinguished only by position." }, "opensAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for when applications open. null means unknown." }, "deadlines": { "type": "array", "items": { "$ref": "#/$defs/deadline" }, "uniqueItems": true, "description": "All deadlines and event boundaries for the opportunity, each either a fixed date or rolling, distinguished by label. Consumers should select by label rather than by array position: the first entry may be a hackathon's start date rather than its application deadline. Conventional labels are published in registries/deadline-labels.json. (Selection-by-label is a consumer convention, not schema-enforceable; see FIELDS.md.)", "examples": [[{ "deadlineType": "fixed", "date": "2026-08-15T23:59:59.000Z", "label": "community feedback" }, { "deadlineType": "fixed", "date": "2026-09-30T23:59:59.000Z", "label": "application" }]] }, "postedAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for when the opportunity was first publicly announced at the source. null means unknown." }, "createdAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for when this entry was created in the Hub. null means unknown." }, "updatedAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for when this entry was last modified in the Hub. null means unknown." }, "fundingDetails": { "description": "The type-specific details for this opportunity: exactly one of the six detail shapes, self-described by its own required `fundingType` tag, which names the shape and equals the top-level `fundingType` (the binding allOf below keeps the two in step).", "oneOf": [{ "$ref": "#/$defs/grant" }, { "$ref": "#/$defs/hackathon" }, { "$ref": "#/$defs/bounty" }, { "$ref": "#/$defs/accelerator" }, { "$ref": "#/$defs/vcFund" }, { "$ref": "#/$defs/rfp" }] } }, "allOf": [{ "$comment": "Binds fundingDetails to the shape the top-level fundingType names, so the two tags cannot disagree. Each branch's `then` narrows `fundingDetails`, a property already declared above, so no branch introduces an undeclared property name \u2014 see the root $comment.", "if": { "properties": { "fundingType": { "const": "grant" } }, "required": ["fundingType"] }, "then": { "type": "object", "properties": { "fundingDetails": { "$ref": "#/$defs/grant" } } } }, { "if": { "properties": { "fundingType": { "const": "hackathon" } }, "required": ["fundingType"] }, "then": { "type": "object", "properties": { "fundingDetails": { "$ref": "#/$defs/hackathon" } } } }, { "if": { "properties": { "fundingType": { "const": "bounty" } }, "required": ["fundingType"] }, "then": { "type": "object", "properties": { "fundingDetails": { "$ref": "#/$defs/bounty" } } } }, { "if": { "properties": { "fundingType": { "const": "accelerator" } }, "required": ["fundingType"] }, "then": { "type": "object", "properties": { "fundingDetails": { "$ref": "#/$defs/accelerator" } } } }, { "if": { "properties": { "fundingType": { "const": "vc_fund" } }, "required": ["fundingType"] }, "then": { "type": "object", "properties": { "fundingDetails": { "$ref": "#/$defs/vcFund" } } } }, { "if": { "properties": { "fundingType": { "const": "rfp" } }, "required": ["fundingType"] }, "then": { "type": "object", "properties": { "fundingDetails": { "$ref": "#/$defs/rfp" } } } }], "$defs": { "organization": { "type": "object", "title": "Organization", "additionalProperties": false, "required": ["name", "slug"], "description": "An organisation sponsoring or operating the opportunity. Embedded on an opportunity as a descriptive summary; the same shape is the standalone Organization directory record.", "$comment": "A deliberate absence, a decision rather than an oversight: there is no `verified` flag, because verification belongs to the publishing relationship \u2014 a user permissioned on a verified org \u2014 not to the organisation itself.", "properties": { "name": { "type": "string", "minLength": 1, "maxLength": 256, "description": "Display name of the organisation." }, "slug": { "type": "string", "pattern": "^[a-z0-9-]+$", "description": "Lowercase URL-safe identifier, and also the organisation's namespace.", "examples": ["example-foundation"] }, "orgType": { "type": "string", "enum": ["foundation", "dao", "company", "protocol", "program", "individual", "other"], "description": "Kind of entity." }, "description": { "type": ["string", "null"], "description": "Short description of the organisation." }, "website": { "type": ["string", "null"], "format": "uri", "description": "The organisation's primary website." }, "logoUrl": { "type": ["string", "null"], "format": "uri", "description": "URL of the organisation's logo image." }, "bannerUrl": { "type": ["string", "null"], "format": "uri", "description": "URL of the organisation's banner or hero image." }, "socialLinks": { "type": "array", "items": { "$ref": "#/$defs/socialLink" }, "uniqueItems": true, "description": "Social and community links for the organisation, one entry per link. The same platform may appear in more than one entry when it has more than one URL; only whole-entry duplicates are rejected." }, "ecosystems": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Ethereum-family ecosystems the organisation operates in. Same open list as the top-level field." }, "contacts": { "type": "array", "items": { "$ref": "#/$defs/contact" }, "description": "Named contact routes into the organisation. Optional, and every field of every entry is optional too." } } }, "contact": { "type": "object", "title": "Contact", "additionalProperties": false, "description": "A named contact route into the organisation. Every property is optional and there is no minimum-one-identifier constraint, so `{}` validates \u2014 deliberately, because not every publisher can or will name a person.", "properties": { "name": { "type": ["string", "null"], "description": "The person's name." }, "role": { "type": ["string", "null"], "description": "Role in the program.", "examples": ["Steward", "Program owner", "Grants Manager"] }, "telegram": { "type": ["string", "null"], "description": "Telegram handle. A handle rather than a URL \u2014 unlike a socialLinks entry with platform 'telegram', which is a link.", "examples": ["@example_steward"] }, "email": { "type": ["string", "null"], "format": "email", "description": "Email address." } } }, "provenance": { "type": "object", "title": "Provenance", "additionalProperties": false, "description": "How this entry reached the Hub and when it was last checked. Every field is optional, so `{}` validates. There is no source URL: link-back to the opportunity runs through the top-level applicationUrl alone.", "properties": { "publisher": { "type": ["string", "null"], "description": "Namespace \u2014 an organisation slug \u2014 this entry was published under. Auto-approval requires the publishing account to be a member of this verified org. May differ from the sponsoring organisation.", "examples": ["filecoin"] }, "submittedBy": { "type": ["string", "null"], "description": "Who submitted or published this entry: a public handle, an organisation slug, or 'community' for anonymous community submissions. The internal account identity is never exposed. This is the attribution carrier for data-partner credit." }, "submittedAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for when the entry was submitted or published to the Hub. Pairs with submittedBy. null means unknown." }, "ingestedVia": { "type": ["string", "null"], "enum": ["publisher_api", "submission", "scrape", "import", "outbox", null], "description": "How this entry entered the Hub. 'outbox' is a one-way push from an upstream source system's outbox; 'import' is a backfill or seed import. Always set server-side by the ingestion layer." }, "originalId": { "type": ["string", "null"], "description": "Identifier of this opportunity in the source system." }, "verifiedAgainstSource": { "type": ["boolean", "null"], "description": "Whether the entry's fields were verified against the live opportunity by the verification-assist job. null means not yet checked." }, "verifiedAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for the last verification. Record-level only \u2014 there is no per-field freshness. null means unknown." }, "snapshotUrl": { "type": ["string", "null"], "format": "uri", "description": "IPFS or archived snapshot of the opportunity taken at verification time." } } }, "socialLink": { "type": "object", "title": "Social link", "additionalProperties": false, "required": ["platform", "url"], "description": "One social or community link: the platform it lives on and its full URL.", "properties": { "platform": { "type": "string", "enum": ["twitter", "discord", "github", "telegram", "farcaster", "forum", "blog"], "description": "Which service the link points at. 'twitter' covers X/Twitter; 'forum' is the governance or community forum; 'blog' is the blog or announcements feed." }, "url": { "type": "string", "format": "uri", "description": "Full URL of the profile, server, group or feed \u2014 a link, not a handle." } }, "examples": [{ "platform": "twitter", "url": "https://x.com/example" }] }, "funding": { "type": "object", "title": "Funding envelope", "additionalProperties": false, "description": "The program-level funding envelope. Single-currency by design, and that rule is document-wide: fundingInfo.currency denominates every monetary amount in the document \u2014 budget, allocated, minAward and maxAward here, plus milestones[].amount, bounty.reward, hackathon.prizes[].amount, accelerator.funding and vcFund.checkSize. No sub-block carries a currency of its own. 'Remaining' is derived at the consumer layer as budget minus allocated, and never stored.", "properties": { "currency": { "type": ["string", "null"], "maxLength": 16, "description": "ISO 4217 code or token symbol denominating every monetary amount in the document: the amounts below, plus milestones[].amount, bounty.reward, hackathon.prizes[].amount, accelerator.funding and vcFund.checkSize.", "examples": ["USD", "OP"] }, "budget": { "type": ["number", "null"], "minimum": 0, "description": "Total program budget in major units." }, "allocated": { "type": ["number", "null"], "minimum": 0, "description": "Amount committed to date in major units \u2014 committed, not necessarily disbursed. Disbursement and delivery are not modelled." }, "minAward": { "type": ["number", "null"], "minimum": 0, "description": "Minimum individual award in major units." }, "maxAward": { "type": ["number", "null"], "minimum": 0, "description": "Maximum individual award in major units." } } }, "amountRange": { "type": "object", "title": "Amount range", "additionalProperties": false, "description": "A lower and upper bound, denominated in the document-wide fundingInfo.currency. Either bound may be absent, expressing an open-ended range.", "properties": { "min": { "type": ["number", "null"], "minimum": 0, "description": "Lower bound in major units of fundingInfo.currency." }, "max": { "type": ["number", "null"], "minimum": 0, "description": "Upper bound in major units of fundingInfo.currency." } } }, "deadline": { "type": "object", "title": "Deadline", "additionalProperties": false, "required": ["deadlineType"], "description": "A single deadline or event boundary. A 'fixed' entry carries a date; 'rolling' means applications are accepted continuously.", "$comment": "There is deliberately no event-anchored or relative form ('opens on X, then 30 days'): an unanchored window does not denote a point in time, so the publisher posts a fixed date when the window actually opens. 'recurring' is likewise out of the enum \u2014 grant.recurring is the only carrier of that concept.", "properties": { "deadlineType": { "type": "string", "enum": ["fixed", "rolling"], "description": "Whether this deadline is a fixed point in time or an open-ended rolling window." }, "date": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z'). Required and non-null when deadlineType is 'fixed', enforced by the if/then below; meaningless, and normally omitted, when deadlineType is 'rolling'." }, "label": { "type": ["string", "null"], "maxLength": 120, "description": "What this deadline is for. Free text; conventional values are published in registries/deadline-labels.json. This is how a consumer tells an application deadline from an event boundary.", "examples": ["application", "community feedback", "registration", "submission", "event start", "event end"] } }, "if": { "properties": { "deadlineType": { "const": "fixed" } }, "required": ["deadlineType"] }, "then": { "required": ["date"], "properties": { "date": { "type": "string" } } }, "examples": [{ "deadlineType": "fixed", "date": "2026-09-30T23:59:59.000Z", "label": "application" }, { "deadlineType": "rolling", "label": "application" }] }, "milestone": { "type": "object", "title": "Milestone", "additionalProperties": false, "description": "One milestone in an opportunity's milestone sequence. Every property is optional \u2014 a publisher may list titles with no amounts, or amounts with no criteria. There is no date field: where a publisher has a due date, it goes into `criteria` as free text.", "properties": { "title": { "type": ["string", "null"], "description": "Short name of the milestone." }, "amount": { "type": ["number", "null"], "minimum": 0, "description": "Payment for this milestone in major units of the document-wide fundingInfo.currency. That denomination rule is a requirement on publishers but crosses two objects, so it is not schema-enforceable; see FIELDS.md. The validator's advisory tier warns when this is present and fundingInfo.currency is absent." }, "criteria": { "type": ["string", "null"], "description": "Free-text acceptance criteria, including any due date." } }, "examples": [{ "title": "Ratings framework published", "amount": 5e4, "criteria": "Published methodology, reviewed by the coalition. Due within 8 weeks of kickoff." }] }, "grant": { "type": "object", "title": "Grant details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'grant': grant-specific attributes not covered by the core fields. May carry nothing beyond its fundingType tag, because core funding and date fields live at the top level.", "properties": { "fundingType": { "const": "grant", "description": "Names this block's shape; equals the top-level fundingType." }, "fundingMechanisms": { "type": "array", "uniqueItems": true, "items": { "type": "string", "enum": ["retroactive", "proactive", "streaming", "quadratic", "matching", "other"] }, "description": "How funds are allocated. An array because mechanisms co-occur: a funder can offer a fixed grant and a matching grant in the same program.", "examples": [["proactive"], ["proactive", "matching"], ["retroactive", "quadratic"]] }, "programModel": { "type": ["string", "null"], "x-since": "1.0.0", "description": "The operating model of the program, as distinct from the funding instrument. An open list rather than a closed enum \u2014 conventional values are published in registries/program-models.json, and a publisher's own vocabulary is valid without a schema change.", "examples": ["grant", "program", "infra", "incentives"] }, "milestoneBased": { "type": ["boolean", "null"], "description": "Whether disbursement is tied to milestones. Pairs with the top-level milestones array." }, "recurring": { "type": ["boolean", "null"], "description": "Whether the program runs in recurring rounds or seasons.", "$comment": "The only carrier of a 'recurring round' concept: deadlines[] has no 'recurring' type, so a recurring program is expressed here plus a rolling or fixed deadline." } } }, "hackathon": { "type": "object", "title": "Hackathon details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'hackathon': hackathon-specific attributes. All dates \u2014 registration, submission, event start and event end \u2014 live in the shared top-level deadlines array, distinguished by label.", "properties": { "fundingType": { "const": "hackathon", "description": "Names this block's shape; equals the top-level fundingType." }, "location": { "type": ["string", "null"], "description": "Physical location, or null for a fully online event." }, "online": { "type": ["boolean", "null"], "description": "Whether the event is also, or only, held online." }, "tracks": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Named tracks or themes participants can build against.", "examples": [["DeFi", "Infra"]] }, "prizes": { "type": "array", "items": { "$ref": "#/$defs/prize" }, "description": "The prize pool, one entry per prize, denominated in the document-wide fundingInfo.currency.", "$comment": "Deliberately not uniqueItems: identical prizes are routine \u2014 several equal-value track prizes, or repeated runner-up awards \u2014 so uniqueness would reject real data." }, "teamSize": { "$ref": "#/$defs/teamSize", "description": "Permitted team size range." } } }, "prize": { "type": "object", "title": "Hackathon prize", "additionalProperties": false, "required": ["amount"], "description": "A single hackathon prize, optionally attributed to a track. Denominated in the document-wide fundingInfo.currency, like every monetary amount in the document.", "properties": { "track": { "type": ["string", "null"], "description": "Track this prize belongs to, where prizes are tracked separately." }, "amount": { "type": "number", "minimum": 0, "description": "Prize amount in major units of fundingInfo.currency." } } }, "teamSize": { "type": "object", "title": "Team size range", "additionalProperties": false, "description": "Permitted team size, as an inclusive range. Either bound may be absent.", "properties": { "min": { "type": ["integer", "null"], "minimum": 1, "description": "Minimum number of team members." }, "max": { "type": ["integer", "null"], "minimum": 1, "description": "Maximum number of team members." } } }, "bounty": { "type": "object", "title": "Bounty details", "additionalProperties": false, "required": ["fundingType", "bountyKind"], "description": "The fundingDetails payload when fundingType is 'bounty': bounty-specific attributes. Two kinds share this block, named by bountyKind. A 'task' bounty is a single scoped piece of work with one stated reward. A 'security' bounty is a standing vulnerability-disclosure program whose payout is a table of tiers, normally graded by severity and by the class of asset in scope. The two kinds carry different required fields, bound by the allOf below.", "properties": { "fundingType": { "const": "bounty", "description": "Names this block's shape; equals the top-level fundingType." }, "bountyKind": { "type": "string", "enum": ["task", "security"], "description": "Which kind of bounty this is, and the discriminator for what the payout looks like. 'task' = one scoped piece of work paying a single reward; 'security' = a standing vulnerability-disclosure program paying against a tier table. This is about payout shape, not about how long the bounty stays open: intake duration lives in the top-level deadlines array, and either kind may be rolling.", "x-stability": "provisional" }, "reward": { "type": "number", "minimum": 0, "description": "The reward paid on completion, in major units of the document-wide fundingInfo.currency. The compensation for a bounty that pays one amount. Exactly one of this and rewardTiers is present on any bounty, enforced by the if/then/else below: they are alternative descriptions of the same money, so a document carrying both leaves a consumer no way to tell which is authoritative. A security bounty is forbidden from carrying it at all and states its amounts in rewardTiers, because a graded program has no single reward and collapsing the table to one number overstates what a typical report pays. That denomination rule is a requirement on publishers but crosses two objects, so it is not schema-enforceable; see FIELDS.md. The validator's advisory tier warns when this is present and fundingInfo.currency is absent." }, "rewardTiers": { "type": "array", "items": { "$ref": "#/$defs/rewardTier" }, "minItems": 1, "description": "The payout table, one entry per tier. The payout table, one entry per tier. Required when bountyKind is 'security', and the alternative to reward on a task bounty that grades its payout \u2014 a placement ladder, for instance \u2014 rather than paying one flat amount. Exactly one of this and reward is present, enforced by the if/then/else below. Array order carries no meaning; select by the tier's own severity, assetType or label.", "x-stability": "provisional" }, "severityScheme": { "type": ["string", "null"], "description": "The published classification the tier severities are drawn from, named so a consumer can tell whose definition of 'critical' is in play. Free text, because these schemes are documents rather than a vocabulary worth governing.", "examples": ["Immunefi Vulnerability Severity Classification System v2.3", "CVSS v4.0"], "x-stability": "provisional" }, "rewardPoolStatus": { "type": ["string", "null"], "enum": ["funded", "unfunded", "unknown", null], "description": "Whether the money behind the advertised amounts is actually held. 'funded' = escrowed or otherwise verifiably reserved; 'unfunded' = advertised as an intent to pay, with nothing set aside; 'unknown' = not published, which is the honest value where the program says nothing and the reason absent does not read as 'unfunded'. Separate from fundingInfo.budget, which carries the amount: a program can name a large maximum and hold nothing against it.", "x-stability": "provisional" }, "difficulty": { "type": ["string", "null"], "enum": ["beginner", "intermediate", "advanced", null], "description": "Self-assessed difficulty, as a hint to applicants. Meaningful on a task bounty; a security program grades by severity in rewardTiers instead." }, "skills": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Skills the task calls for. Free text.", "examples": [["Frontend", "Design"]] }, "platform": { "type": ["string", "null"], "description": "Platform hosting the bounty.", "examples": ["Gitcoin", "Layer3", "Superteam Earn", "Immunefi"] } }, "$comment": "Compensation is EXACTLY ONE of reward or rewardTiers, on either kind \u2014 the two are alternative descriptions of the same money, and a document carrying both has two sources of truth for what a participant is paid. A security bounty is additionally required to use the table. bountyKind therefore names the domain; which compensation field is present names the shape. Each branch mentions only properties declared above, so none introduces an undeclared property name \u2014 see the root $comment. Written as bare if/then/else rather than a oneOf of branches because a oneOf at this level defeats the type generator, which emits an index signature instead of the interface.", "if": { "properties": { "bountyKind": { "const": "security" } }, "required": ["bountyKind"] }, "then": { "required": ["rewardTiers"], "properties": { "reward": false } }, "else": { "if": { "required": ["reward"] }, "then": { "properties": { "rewardTiers": false } }, "else": { "required": ["rewardTiers"] } } }, "rewardTier": { "type": "object", "title": "Reward tier", "additionalProperties": false, "required": ["payout"], "minProperties": 2, "description": "One row of a bounty's payout table: what is being paid for, and what it pays. The 'what for' is a selector \u2014 severity and assetType form a compound coordinate where a program grades on both, and label carries a grading axis neither describes. Each is individually optional so a program grading on one axis carries only that one, but at least one is required by the minProperties rule below: a row with no selector is an anonymous rule nothing can be matched against, not a tier. The payout is the other required part, because a tier that names no amount and no payout model is not a tier either.", "properties": { "severity": { "type": "string", "description": "Severity band this row pays for. An open list rather than a closed enum \u2014 conventional values are published in registries/bounty-severities.json, and a program's own vocabulary is valid without a schema change. Name the scheme these are drawn from in severityScheme.", "examples": ["critical", "high"], "x-stability": "provisional" }, "assetType": { "type": "string", "description": "Class of in-scope asset this row pays for, where a program grades the same severity differently by what was found. An open list rather than a closed enum \u2014 conventional values are published in registries/bounty-asset-types.json. Absent where a program grades on severity alone.", "examples": ["smart_contract", "websites_and_applications"], "x-stability": "provisional" }, "label": { "type": "string", "maxLength": 120, "description": "What this row pays for, in the publisher's own words, where severity and assetType do not describe it \u2014 a placement in a prize ladder, or a named category. This is a selector, not a caption: it is how a consumer picks the row out when the structured dimensions do not apply. Where it accompanies severity or assetType it reads as a caption, and a consumer that facets should prefer the structured dimensions. Free text.", "examples": ["1st place", "Best use of the SDK"], "x-stability": "provisional" }, "payout": { "$ref": "#/$defs/payout", "description": "What this tier pays, and on which model." } }, "$comment": "minProperties: 2 is how 'at least one selector' is expressed. payout is required and the object is closed to four properties, so a second property can only be severity, assetType or label \u2014 and all three are non-nullable, deliberately breaking this schema's usual optional-means-nullable convention: a null selector would count toward minProperties while selecting nothing, so for these three absence is the only way to say 'not used'. An anyOf of required-branches would say the same thing and read better, but an anyOf at this level defeats the type generator, which emits an index-signature union in place of the interface \u2014 the same trap as an allOf here." }, "payout": { "type": "object", "title": "Payout", "additionalProperties": false, "required": ["model"], "description": "What a tier pays, tagged by the model that determines which of the amounts below apply. Every amount is in major units of the document-wide fundingInfo.currency, the same rule that governs every other monetary value in the document. Amounts that do not apply to the stated model are meaningless and normally omitted, the same convention deadline.date follows.", "properties": { "model": { "type": "string", "enum": ["fixed", "range", "up_to", "percentage", "discretionary"], "description": "How this tier's payout is determined. 'fixed' pays one amount; 'range' pays somewhere between two bounds; 'up_to' names a ceiling with no floor; 'percentage' pays a share of a quantity the basis field names, optionally bounded by floor and cap; 'discretionary' names no figure at all, because the payer decides case by case, and carries none of the amount fields. The last is a real published position, not missing data \u2014 programs run numeric tiers and discretionary tiers side by side in the same table.", "x-stability": "provisional" }, "amount": { "type": ["number", "null"], "minimum": 0, "description": "The amount paid, where the model is 'fixed'. Required and non-null for that model, enforced by the if/then/else below.", "x-stability": "provisional" }, "min": { "type": ["number", "null"], "minimum": 0, "description": "Lower bound, where the model is 'range'. Required and non-null for that model, enforced by the if/then/else below.", "x-stability": "provisional" }, "max": { "type": ["number", "null"], "minimum": 0, "description": "Upper bound, where the model is 'range' or 'up_to'. Required and non-null for both, enforced by the if/then/else below.", "x-stability": "provisional" }, "percent": { "type": ["number", "null"], "minimum": 0, "maximum": 100, "description": "Share this tier pays, as a percentage between 0 and 100 \u2014 a program paying 'up to 10% of funds affected' carries 10 here. What the share is *of* is named by basis, not assumed. Required and non-null where the model is 'percentage', enforced by the if/then/else below.", "x-stability": "provisional" }, "basis": { "type": "string", "enum": ["value_at_risk", "economic_damage"], "description": "What the percentage is a share of. Required where the model is 'percentage' and forbidden on every other model, enforced by the if/then/else below. 'value_at_risk' = the funds the finding could have taken, the construction most programs publish; 'economic_damage' = the loss actually caused, which some programs cap against instead. The two are not interchangeable and a program that states one is not stating the other, which is why the model tag no longer asserts a basis of its own. The list grows by spec release as programs attest a new one.", "x-stability": "provisional" }, "floor": { "type": ["number", "null"], "minimum": 0, "description": "Least the tier pays regardless of the computed figure, where a percentage model states a minimum. Optional; absent means the computation is unbounded below.", "x-stability": "provisional" }, "cap": { "type": ["number", "null"], "minimum": 0, "description": "Most the tier pays regardless of the computed figure, where a percentage model states a maximum. Optional; absent means the computation is unbounded above.", "x-stability": "provisional" } }, "$comment": "Binds the amounts to the model, as a nested if/then/else chain rather than an allOf of branches: an allOf at this level defeats the type generator, which emits an index signature instead of the interface. Every branch names only properties already declared above, so none introduces an undeclared property name \u2014 see the root $comment. Each branch both requires the amounts its model needs and forbids the ones belonging to other models, so the model tag is a real discriminator rather than a hint: a 'discretionary' payout carrying an amount, or a 'fixed' one carrying a range, does not validate. The final else is 'discretionary', which names no figure at all. 'percentage' additionally requires a basis, so the tag never implies what the share is of.", "if": { "properties": { "model": { "const": "fixed" } }, "required": ["model"] }, "then": { "required": ["amount"], "properties": { "amount": { "type": "number" }, "min": false, "max": false, "percent": false, "basis": false, "floor": false, "cap": false } }, "else": { "if": { "properties": { "model": { "const": "range" } }, "required": ["model"] }, "then": { "required": ["min", "max"], "properties": { "min": { "type": "number" }, "max": { "type": "number" }, "amount": false, "percent": false, "basis": false, "floor": false, "cap": false } }, "else": { "if": { "properties": { "model": { "const": "up_to" } }, "required": ["model"] }, "then": { "required": ["max"], "properties": { "max": { "type": "number" }, "amount": false, "min": false, "percent": false, "basis": false, "floor": false, "cap": false } }, "else": { "if": { "properties": { "model": { "const": "percentage" } }, "required": ["model"] }, "then": { "required": ["percent", "basis"], "properties": { "percent": { "type": "number" }, "basis": { "type": "string" }, "amount": false, "min": false, "max": false } }, "else": { "properties": { "amount": false, "min": false, "max": false, "percent": false, "basis": false, "floor": false, "cap": false } } } } }, "examples": [{ "model": "range", "min": 15e3, "max": 25e4 }, { "model": "percentage", "percent": 10, "basis": "value_at_risk", "floor": 1e5, "cap": 1e6 }, { "model": "discretionary" }] }, "accelerator": { "type": "object", "title": "Accelerator details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'accelerator': accelerator-specific attributes. The application deadline lives in the shared top-level deadlines array with label 'application'.", "properties": { "fundingType": { "const": "accelerator", "description": "Names this block's shape; equals the top-level fundingType." }, "programDurationWeeks": { "type": ["integer", "null"], "minimum": 0, "description": "Length of the program in weeks." }, "batchSize": { "type": ["integer", "null"], "minimum": 0, "description": "Number of teams accepted per cohort." }, "equity": { "type": ["string", "null"], "description": "Equity taken, expressed as a string because programs state it in incomparable ways.", "examples": ["5%", "none", "up to 7% SAFE"] }, "funding": { "type": ["number", "null"], "minimum": 0, "description": "Investment or stipend offered per team, in major units of the document-wide fundingInfo.currency. That denomination rule is a requirement on publishers but crosses two objects, so it is not schema-enforceable; see FIELDS.md. The validator's advisory tier warns when this is present and fundingInfo.currency is absent." }, "stage": { "type": ["string", "null"], "enum": ["pre-seed", "seed", "series-a", null], "description": "Company stage the program targets." }, "location": { "type": ["string", "null"], "description": "Physical location, or null for a fully remote program." }, "online": { "type": ["boolean", "null"], "description": "Whether the program is also, or only, run remotely." } } }, "vcFund": { "type": "object", "title": "VC fund details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'vc_fund': venture-fund-specific attributes. A fund is an ongoing source of capital rather than a round, so it carries no deadline of its own.", "properties": { "fundingType": { "const": "vc_fund", "description": "Names this block's shape; equals the top-level fundingType." }, "checkSize": { "$ref": "#/$defs/amountRange", "description": "Typical investment size, as a range denominated in the document-wide fundingInfo.currency." }, "stages": { "type": "array", "items": { "type": "string", "enum": ["pre-seed", "seed", "series-a", "series-b+", "growth"] }, "uniqueItems": true, "description": "Investment stages the fund participates in." }, "thesis": { "type": ["string", "null"], "description": "Investment thesis, in the fund's own words." }, "portfolio": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Named portfolio companies, where the fund publishes them." }, "contactMethod": { "type": ["string", "null"], "enum": ["email", "form", "intro-only", null], "description": "How the fund prefers to be approached. 'intro-only' means a warm introduction is required." }, "activelyInvesting": { "type": ["boolean", "null"], "description": "Whether the fund is currently deploying capital." } } }, "rfp": { "type": "object", "title": "RFP details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'rfp': RFP-specific attributes. The issuing organisation is operatingOrganizations[0], the budget is the top-level fundingInfo envelope, and the proposal deadline is a deadlines entry labelled 'application'.", "properties": { "fundingType": { "const": "rfp", "description": "Names this block's shape; equals the top-level fundingType." }, "scope": { "type": ["string", "null"], "description": "Scope of work, as one free-text field. In-scope and out-of-scope prose both live here.", "$comment": "There is deliberately no separate outOfScope field \u2014 same philosophy as requirements and milestone criteria: one free-text field rather than a structure publishers would fill inconsistently." }, "requirements": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Free-text statements of what the work must deliver. RFP-only, and deliberately not split into hard and soft. What a proposal must contain goes in the top-level prerequisites instead.", "examples": [["Methodology must be reproducible from public evidence."]] } } } } };
var schema32 = { "type": "object", "title": "Grant details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'grant': grant-specific attributes not covered by the core fields. May carry nothing beyond its fundingType tag, because core funding and date fields live at the top level.", "properties": { "fundingType": { "const": "grant", "description": "Names this block's shape; equals the top-level fundingType." }, "fundingMechanisms": { "type": "array", "uniqueItems": true, "items": { "type": "string", "enum": ["retroactive", "proactive", "streaming", "quadratic", "matching", "other"] }, "description": "How funds are allocated. An array because mechanisms co-occur: a funder can offer a fixed grant and a matching grant in the same program.", "examples": [["proactive"], ["proactive", "matching"], ["retroactive", "quadratic"]] }, "programModel": { "type": ["string", "null"], "x-since": "1.0.0", "description": "The operating model of the program, as distinct from the funding instrument. An open list rather than a closed enum \u2014 conventional values are published in registries/program-models.json, and a publisher's own vocabulary is valid without a schema change.", "examples": ["grant", "program", "infra", "incentives"] }, "milestoneBased": { "type": ["boolean", "null"], "description": "Whether disbursement is tied to milestones. Pairs with the top-level milestones array." }, "recurring": { "type": ["boolean", "null"], "description": "Whether the program runs in recurring rounds or seasons.", "$comment": "The only carrier of a 'recurring round' concept: deadlines[] has no 'recurring' type, so a recurring program is expressed here plus a rolling or fixed deadline." } } };
var schema39 = { "type": "object", "title": "Accelerator details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'accelerator': accelerator-specific attributes. The application deadline lives in the shared top-level deadlines array with label 'application'.", "properties": { "fundingType": { "const": "accelerator", "description": "Names this block's shape; equals the top-level fundingType." }, "programDurationWeeks": { "type": ["integer", "null"], "minimum": 0, "description": "Length of the program in weeks." }, "batchSize": { "type": ["integer", "null"], "minimum": 0, "description": "Number of teams accepted per cohort." }, "equity": { "type": ["string", "null"], "description": "Equity taken, expressed as a string because programs state it in incomparable ways.", "examples": ["5%", "none", "up to 7% SAFE"] }, "funding": { "type": ["number", "null"], "minimum": 0, "description": "Investment or stipend offered per team, in major units of the document-wide fundingInfo.currency. That denomination rule is a requirement on publishers but crosses two objects, so it is not schema-enforceable; see FIELDS.md. The validator's advisory tier warns when this is present and fundingInfo.currency is absent." }, "stage": { "type": ["string", "null"], "enum": ["pre-seed", "seed", "series-a", null], "description": "Company stage the program targets." }, "location": { "type": ["string", "null"], "description": "Physical location, or null for a fully remote program." }, "online": { "type": ["boolean", "null"], "description": "Whether the program is also, or only, run remotely." } } };
var schema42 = { "type": "object", "title": "RFP details", "additionalProperties": false, "required": ["fundingType"], "description": "The fundingDetails payload when fundingType is 'rfp': RFP-specific attributes. The issuing organisation is operatingOrganizations[0], the budget is the top-level fundingInfo envelope, and the proposal deadline is a deadlines entry labelled 'application'.", "properties": { "fundingType": { "const": "rfp", "description": "Names this block's shape; equals the top-level fundingType." }, "scope": { "type": ["string", "null"], "description": "Scope of work, as one free-text field. In-scope and out-of-scope prose both live here.", "$comment": "There is deliberately no separate outOfScope field \u2014 same philosophy as requirements and milestone criteria: one free-text field rather than a structure publishers would fill inconsistently." }, "requirements": { "type": "array", "items": { "type": "string", "minLength": 1 }, "uniqueItems": true, "description": "Free-text statements of what the work must deliver. RFP-only, and deliberately not split into hard and soft. What a proposal must contain goes in the top-level prerequisites instead.", "examples": [["Methodology must be reproducible from public evidence."]] } } };
var schema46 = { "type": "object", "title": "Provenance", "additionalProperties": false, "description": "How this entry reached the Hub and when it was last checked. Every field is optional, so `{}` validates. There is no source URL: link-back to the opportunity runs through the top-level applicationUrl alone.", "properties": { "publisher": { "type": ["string", "null"], "description": "Namespace \u2014 an organisation slug \u2014 this entry was published under. Auto-approval requires the publishing account to be a member of this verified org. May differ from the sponsoring organisation.", "examples": ["filecoin"] }, "submittedBy": { "type": ["string", "null"], "description": "Who submitted or published this entry: a public handle, an organisation slug, or 'community' for anonymous community submissions. The internal account identity is never exposed. This is the attribution carrier for data-partner credit." }, "submittedAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for when the entry was submitted or published to the Hub. Pairs with submittedBy. null means unknown." }, "ingestedVia": { "type": ["string", "null"], "enum": ["publisher_api", "submission", "scrape", "import", "outbox", null], "description": "How this entry entered the Hub. 'outbox' is a one-way push from an upstream source system's outbox; 'import' is a backfill or seed import. Always set server-side by the ingestion layer." }, "originalId": { "type": ["string", "null"], "description": "Identifier of this opportunity in the source system." }, "verifiedAgainstSource": { "type": ["boolean", "null"], "description": "Whether the entry's fields were verified against the live opportunity by the verification-assist job. null means not yet checked." }, "verifiedAt": { "type": ["string", "null"], "format": "date-time", "pattern": "Z$", "description": "RFC 3339 timestamp in UTC (trailing 'Z') for the last verification. Record-level only \u2014 there is no per-field freshness. null means unknown." }, "snapshotUrl": { "type": ["string", "null"], "format": "uri", "description": "IPFS or archived snapshot of the opportunity taken at verification time." } } };
